-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Shared, read-only navigation geometry. Coordinates in Coord use APR's x/y
-- ordering; from/to positions supplied by the routing engine use world x/y.
local Constants = APR.NavigationConstants.Preview

APR.navigationPreview = {}
local Preview = APR.navigationPreview

local function finite(value)
    return type(value) == "number"
        and not (issecretvalue and issecretvalue(value))
        and value == value
        and value > -math.huge
        and value < math.huge
end--[[APR_DIAG]]; finite = APRTrace("APR-Core/features/navigation/Preview.lua:13:finite#1", finite)--[[/APR_DIAG]]

function Preview:Point(value, generated)
    if type(value) ~= "table" then return nil end
    local coord = value.Coord or value.coord
    if not coord or not finite(coord.x) or not finite(coord.y) then return nil end
    local point = {}
    for key, entry in pairs(value) do
        point[key] = entry
    end
    point.Coord = { x = coord.x, y = coord.y }
    point.generated = generated == true or value.generated == true
    point.uiMapID = coord.mapID or value.uiMapID or value.mapID or value.Zone
    point.instanceID = value.instanceID or coord.instanceID or self:GetMapInstance(point.uiMapID)
    local data = APR.NavigationData
    if finite(point.instanceID) and data and data.GetWorldInstanceID then
        if point.region and data.GetPositionRegion then point.region = data:GetPositionRegion(point) end
        point.instanceID = data:GetWorldInstanceID(point.instanceID)
    end
    return point
end--[[APR_DIAG]]; Preview.Point = APRTrace("APR-Core/features/navigation/Preview.lua:21:Preview:Point#2", Preview.Point)--[[/APR_DIAG]]

local function enginePoint(position, source)
    if type(position) ~= "table" or not finite(position.x) or not finite(position.y) then return nil end
    return {
        Coord = { x = position.y, y = position.x },
        instanceID = position.instanceID,
        uiMapID = position.uiMapID,
        generated = true,
        kind = "arrival",
        arrival = true,
        label = source.label or source.instruction,
        mandatory = source.mandatory,
        accessKey = position.accessKey,
        floor = position.floor,
        z = position.z,
    }
end--[[APR_DIAG]]; enginePoint = APRTrace("APR-Core/features/navigation/Preview.lua:41:enginePoint#3", enginePoint)--[[/APR_DIAG]]

local function append(points, point)
    if not point then return end
    local previous = points[#points]
    if
        previous
        and previous.Coord.x == point.Coord.x
        and previous.Coord.y == point.Coord.y
        and previous.instanceID == point.instanceID
        and (previous.floor == nil or point.floor == nil or previous.floor == point.floor)
        and (previous.z == nil or point.z == nil or previous.z == point.z)
        and (previous.accessKey == nil or point.accessKey == nil or previous.accessKey == point.accessKey)
        and not point.breakBefore
    then
        -- A coincident walk must not swallow a mandatory transport/probe or its
        -- discontinuity. An authored objective keeps its real route identity.
        local keep = previous
        if
            previous.generated
            and (
                not point.generated
                or (point.kind ~= "walk" and point.kind ~= "arrival")
                or previous.kind == "walk"
                or previous.kind == "arrival"
            )
        then
            keep = point
        end
        keep.breakBefore = previous.breakBefore or point.breakBefore
        keep.breakAfter = previous.breakAfter or point.breakAfter
        keep.mandatory = previous.mandatory or point.mandatory
        keep.walkStep = previous.walkStep or point.walkStep
        points[#points] = keep
        return
    end
    points[#points + 1] = point
end--[[APR_DIAG]]; append = APRTrace("APR-Core/features/navigation/Preview.lua:58:append#4", append)--[[/APR_DIAG]]

function Preview:BuildRoutePoints(step, index, steps)
    if not step then
        step, index, steps = APR:GetCurrentStep()
    end
    if not step or not index or not steps then return {} end
    local playerMapID = C_Map and C_Map.GetBestMapForUnit and C_Map.GetBestMapForUnit("player")
    local cache = self.routeCache
    if
        cache
        and cache.step == step
        and cache.steps == steps
        and cache.index == index
        and cache.revision == APR.stepRevision
        and cache.playerMapID == playerMapID
        and cache.coord == step.Coord
        and cache.noArrow == step.NoArrow
    then
        return cache.points
    end
    local definition = APR.RouteQuestStepList and APR.RouteQuestStepList[APR.ActiveRoute]
    local routeMapID = definition and definition.mapID or tonumber((APR.ActiveRoute or ""):match("^(%d+)"))
    local points = {}
    local cursor = index
    while cursor <= #steps do
        local current = cursor == index and step or steps[cursor]
        if not current then break end
        local destinationPin = current._mapWaypoint or current.serviceWaypoint
        local visible = destinationPin or not APR.StepFilterQoL or APR:StepFilterQoL(current)
        if visible then
            if current.NoArrow then break end
            local coord, zone
            if destinationPin then
                coord = current.Coord
            else
                coord, zone = APR:GetStepCoord(current, routeMapID, playerMapID)
            end
            if not coord then break end
            local uiMapID = coord.mapID or zone or current.Zone or routeMapID
            if type(uiMapID) ~= "number" then uiMapID = routeMapID end
            append(
                points,
                self:Point({
                    Coord = coord,
                    uiMapID = uiMapID,
                    instanceID = current.instanceID,
                    routeIndex = cursor,
                    step = current,
                    kind = current._mapWaypoint and "map_waypoint" or (current.Waypoint and "waypoint" or "objective"),
                    label = destinationPin and APR.Services:GetLabel() or nil,
                }, destinationPin)
            )
            if not current.Waypoint then break end
        end
        cursor = cursor + 1
    end
    self.routeCache = {
        step = step,
        steps = steps,
        index = index,
        revision = APR.stepRevision,
        playerMapID = playerMapID,
        coord = step.Coord,
        noArrow = step.NoArrow,
        points = points,
    }
    return points
end--[[APR_DIAG]]; Preview.BuildRoutePoints = APRTrace("APR-Core/features/navigation/Preview.lua:95:Preview:BuildRoutePoints#5", Preview.BuildRoutePoints)--[[/APR_DIAG]]

function Preview:Build(guidance, step, index, steps, cursor)
    local routePoints = self:BuildRoutePoints(step, index, steps)
    local active = guidance and guidance[cursor or 1]
    local pathCursor = active and (active.pathAimIndex or active.pathCursor)
    local pathAimPoint = active and active.pathAimPoint
    local cached = self.guidanceCache
    -- Published guidance is immutable. Arrow and map refreshes can reuse its
    -- points until the queue advances or the authored route cache changes.
    if
        cursor
        and cached
        and cached.guidance == guidance
        and cached.cursor == cursor
        and cached.pathCursor == pathCursor
        and cached.pathAimPoint == pathAimPoint
        and cached.routePoints == routePoints
    then
        return cached.points
    end
    local points = {}
    for guidanceIndex = cursor or 1, #(guidance or {}) do
        local entry = guidance[guidanceIndex]
        local personalAction = entry.sourceFree == true and entry.action ~= nil
        -- A personal action has no fixed cast location. Keep any preceding
        -- approach walk and its destination, but never pin the old cast origin.
        local kind = entry.kind or entry.type
        local walkingPath = kind == "walk" and entry.path and #entry.path > 1
        local point = not personalAction and not walkingPath and self:Point(entry, true) or nil
        if walkingPath then
            local first = guidanceIndex == (cursor or 1) and (pathCursor or 2) or 1
            local aim = guidanceIndex == (cursor or 1) and pathAimPoint
            for pathIndex = aim and first - 1 or first, #entry.path do
                local bend = enginePoint(pathIndex < first and aim or entry.path[pathIndex], entry)
                if bend then
                    bend.kind = "walk"
                    bend.breakBefore = entry.breakBefore and pathIndex == 1 or nil
                    bend.estimated = entry.estimated
                    bend.walkStep = entry
                    bend.arrival = nil
                    bend.uiMapID = bend.uiMapID or entry.uiMapID
                    bend.terrainBend = entry.estimated or pathIndex < #entry.path
                    append(points, bend)
                end
            end
        else
            append(points, point)
        end
        if (point or personalAction) and entry.to and kind ~= "walk" and kind ~= "waypoint" and not entry.arrival then
            local arrival = enginePoint(entry.to, entry)
            if arrival then
                arrival.breakBefore = personalAction == true
                    or (
                        point
                        and point.instanceID ~= nil
                        and arrival.instanceID ~= nil
                        and point.instanceID ~= arrival.instanceID
                    )
                append(points, arrival)
            end
        end
    end
    for routePointIndex, point in ipairs(routePoints) do
        local nextPoint = self:Point(point, false)
        if nextPoint and active and routePointIndex > 1 then nextPoint.guideContinuation = true end
        if
            nextPoint
            and (
                nextPoint.kind == "map_waypoint"
                or (nextPoint.step and nextPoint.step.serviceWaypoint)
                or (routePointIndex == 1 and points[#points] and points[#points].walkStep)
            )
        then
            local last = points[#points]
            -- Render the pin during planning too. A line to it requires a
            -- published itinerary whose final point reaches the destination.
            nextPoint.breakBefore = not last
                or last.instanceID ~= nextPoint.instanceID
                or last.Coord.x ~= nextPoint.Coord.x
                or last.Coord.y ~= nextPoint.Coord.y
        end
        append(points, nextPoint)
    end
    if cursor then
        self.guidanceCache = {
            guidance = guidance,
            cursor = cursor,
            pathCursor = pathCursor,
            pathAimPoint = pathAimPoint,
            routePoints = routePoints,
            points = points,
        }
    end
    return points
end--[[APR_DIAG]]; Preview.Build = APRTrace("APR-Core/features/navigation/Preview.lua:163:Preview:Build#6", Preview.Build)--[[/APR_DIAG]]

function Preview:GetPoints()
    local navigation = APR.navigation
    if
        not APR.ActiveRoute
        and not (APR.Services and APR.Services.active)
        and not (navigation and navigation.queue and #navigation.queue > 0)
        and not (navigation and navigation.GetPreview and not navigation.queue)
    then
        return Constants.emptyPublishedPoints
    end
    -- External providers without a published queue cannot advertise when their
    -- geometry changes. Keep their existing pull contract.
    if navigation and navigation.GetPreview and not navigation.queue then
        return navigation:GetPreview() or {}
    end
    local progress = APRData and APRData[APR.PlayerID]
    local route = APR.ActiveRoute
    local index = progress and route and progress[route]
    local definition = APR.RouteQuestStepList and APR.RouteQuestStepList[route]
    -- Route editors may replace a source step without changing the enclosing
    -- definition. Observe that identity even when the arrow is disabled.
    local sourceSteps = definition and (definition.steps or definition)
    local sourceStep = sourceSteps and index and sourceSteps[index]
    local playerMapID = C_Map and C_Map.GetBestMapForUnit and C_Map.GetBestMapForUnit("player")
    local queue, cursor, state =
        navigation and navigation.queue, navigation and navigation.cursor, navigation and navigation.state
    local active = queue and queue[cursor or 1]
    local pathCursor = active and (active.pathAimIndex or active.pathCursor)
    local pathAimPoint = active and active.pathAimPoint
    local runtime = APR.runtimeRouteStep
    local coord = runtime and runtime.step and runtime.step.Coord
    local noArrow = runtime and runtime.step and runtime.step.NoArrow
    local cached = self.publishedCache
    local service = APR.Services and APR.Services.active
    if
        cached
        and cached.route == route
        and cached.index == index
        and cached.definition == definition
        and cached.sourceSteps == sourceSteps
        and cached.sourceStep == sourceStep
        and cached.revision == APR.stepRevision
        and cached.playerMapID == playerMapID
        and cached.queue == queue
        and cached.walkingPreview == (navigation and navigation.walkingPreview)
        and cached.waypointLeg == (navigation and navigation.waypointPendingLeg)
        and cached.waypointPreview == (navigation and navigation.waypointPreview)
        and cached.cursor == cursor
        and cached.pathCursor == pathCursor
        and cached.pathAimPoint == pathAimPoint
        and cached.state == state
        and cached.service == service
        and cached.runtime == runtime
        and cached.coord == coord
        and cached.noArrow == noArrow
        and cached.routeCache == self.routeCache
    then
        return cached.points
    end

    -- Resolving the effective route may activate parallel steps. Do it only
    -- when its identity changes, not on every minimap refresh.
    local points = navigation and navigation.GetPreview and navigation:GetPreview() or self:BuildRoutePoints()
    runtime = APR.runtimeRouteStep
    self.publishedCache = {
        route = route,
        index = index,
        definition = definition,
        revision = APR.stepRevision,
        sourceSteps = sourceSteps,
        sourceStep = sourceStep,
        playerMapID = playerMapID,
        queue = queue,
        walkingPreview = navigation and navigation.walkingPreview,
        waypointLeg = navigation and navigation.waypointPendingLeg,
        waypointPreview = navigation and navigation.waypointPreview,
        cursor = cursor,
        pathCursor = pathCursor,
        pathAimPoint = pathAimPoint,
        state = state,
        service = service,
        runtime = runtime,
        coord = runtime and runtime.step and runtime.step.Coord,
        noArrow = runtime and runtime.step and runtime.step.NoArrow,
        routeCache = self.routeCache,
        points = points,
    }
    return points
end--[[APR_DIAG]]; Preview.GetPoints = APRTrace("APR-Core/features/navigation/Preview.lua:258:Preview:GetPoints#7", Preview.GetPoints)--[[/APR_DIAG]]

function Preview:CanConnect(a, b)
    if not a or not b or a.breakAfter or b.breakBefore then return false end
    if a.instanceID ~= nil and b.instanceID ~= nil and a.instanceID ~= b.instanceID then return false end
    return true
end--[[APR_DIAG]]; Preview.CanConnect = APRTrace("APR-Core/features/navigation/Preview.lua:348:Preview:CanConnect#8", Preview.CanConnect)--[[/APR_DIAG]]

